19	public sealed class QdrantVectorStore : IVectorStore
20	{
21	    /// <summary>The name of this database for telemetry purposes.</summary>
22	    private const string DatabaseName = "Qdrant";
23	
24	    /// <summary>Qdrant client that can be used to manage the collections and points in a Qdrant store.</summary>
25	    private readonly MockableQdrantClient _qdrantClient;
26	
27	    /// <summary>Optional configuration options for this class.</summary>
28	    private readonly QdrantVectorStoreOptions _options;
29	
30	    /// <summary>
31	    /// Initializes a new instance of the <see cref="QdrantVectorStore"/> class.
32	    /// </summary>
33	    /// <param name="qdrantClient">Qdrant client that can be used to manage the collections and points in a Qdrant store.</param>
34	    /// <param name="options">Optional configuration options for this class.</param>
35	    public QdrantVectorStore(QdrantClient qdrantClient, QdrantVectorStoreOptions? options = default)
36	        : this(new MockableQdrantClient(qdrantClient), options)
37	    {
38	    }
39	
40	    /// <summary>
41	    /// Initializes a new instance of the <see cref="QdrantVectorStore"/> class.
42	    /// </summary>
43	    /// <param name="qdrantClient">Qdrant client that can be used to manage the collections and points in a Qdrant store.</param>
44	    /// <param name="options">Optional configuration options for this class.</param>
45	    internal QdrantVectorStore(MockableQdrantClient qdrantClient, QdrantVectorStoreOptions? options = default)
46	    {
47	        Verify.NotNull(qdrantClient);
48	
49	        this._qdrantClient = qdrantClient;
50	        this._options = options ?? new QdrantVectorStoreOptions();
51	    }
52	
53	    /// <inheritdoc />
54	    public IVectorStoreRecordCollection<TKey, TRecord> GetCollection<TKey, TRecord>(string name, VectorStoreRecordDefinition? vectorStoreRecordDefinition = null) where TRecord : class
55	    {
56	        if (typeof(TKey) != typeof(ulong) && typeof(TKey) != typeof(Guid))
57	        {
58	            throw new NotSupportedException("Only ulong and Guid keys are supported.");
59	        }
60	
61	        if (this._options.VectorStoreCollectionFactory is not null)
62	        {
63	            return this._options.VectorStoreCollectionFactory.CreateVectorStoreRecordCollection<TKey, TRecord>(this._qdrantClient.QdrantClient, name, vectorStoreRecordDefinition);
64	        }
65	
66	        var directlyCreatedStore = new QdrantVectorStoreRecordCollection<TRecord>(this._qdrantClient, name, new QdrantVectorStoreRecordCollectionOptions<TRecord>() { VectorStoreRecordDefinition = vectorStoreRecordDefinition });
67	        var castCreatedStore = directlyCreatedStore as IVectorStoreRecordCollection<TKey, TRecord>;
68	        return castCreatedStore!;
69	    }
70	
71	    /// <inheritdoc />
72	    public async IAsyncEnumerable<string> ListCollectionNamesAsync([EnumeratorCancellation] CancellationToken cancellationToken = default)
73	    {
74	        IReadOnlyList<string> collections;
75	
76	        try
77	        {
78	            collections = await this._qdrantClient.ListCollectionsAsync(cancellationToken).ConfigureAwait(false);
79	        }
80	        catch (RpcException ex)
81	        {
82	            throw new VectorStoreOperationException("Call to vector store failed.", ex)
83	            {
84	                VectorStoreType = DatabaseName,
85	                OperationName = "ListCollections"
86	            };
87	        }
88	
89	        foreach (var collection in collections)
90	        {
91	            yield return collection;
92	        }
93	    }
94	}
