using Microsoft.Extensions.DependencyInjection;
using Microsoft.SemanticKernel.Connectors.Qdrant;
using Microsoft.SemanticKernel.Data;
using Qdrant.Client;

namespace Microsoft.SemanticKernel;

/// <summary>
/// Extension methods to register Qdrant <see cref="IVectorStore"/> instances on the <see cref="IKernelBuilder"/>.
/// </summary>
public static class QdrantKernelBuilderExtensions
{
    /// <summary>
    /// Register a Qdrant <see cref="IVectorStore"/> with the specified service ID. If <paramref name="host"/> is null, the <see cref="QdrantClient"/> is retrieved from the dependency injection container, otherwise it is constructed using the provided parameters.
    /// </summary>
    /// <param name="builder">The builder to register the <see cref="IVectorStore"/> on.</param>
    /// <param name="host">The Qdrant service host name. If null, the <see cref="QdrantClient"/> is resolved from the dependency injection container.</param>
    /// <param name="port">The Qdrant service port.</param>
    /// <param name="https">A value indicating whether to use HTTPS for communicating with Qdrant.</param>
    /// <param name="apiKey">The Qdrant service API key for authentication.</param>
    /// <param name="options">Optional options to further configure the <see cref="IVectorStore"/>.</param>
    /// <param name="serviceId">An optional service id to use as the service key.</param>
    /// <returns>The kernel builder.</returns>
    public static IKernelBuilder AddQdrantVectorStore(this IKernelBuilder builder, string? host = default, int port = 6334, bool https = false, string? apiKey = default, QdrantVectorStoreOptions? options = default, string? serviceId = default)
    {
        // If we are not constructing the QdrantClient, add the IVectorStore as transient, since we
        // cannot make assumptions about how QdrantClient is being managed.
        if (host is null)
        {
            builder.Services.AddKeyedTransient<IVectorStore>(
                serviceId,
                (sp, obj) =>
                {
                    var qdrantClient = sp.GetRequiredService<QdrantClient>();
                    var selectedOptions = options ?? sp.GetService<QdrantVectorStoreOptions>();

                    return new QdrantVectorStore(
                        qdrantClient,
                        selectedOptions);
                });
        }
        else
        {
            builder.Services.AddKeyedSingleton<IVectorStore>(
                serviceId,
                (sp, obj) =>
                {
                    var qdrantClient = new QdrantClient(host, port, https, apiKey);
                    var selectedOptions = options ?? sp.GetService<QdrantVectorStoreOptions>();

                    return new QdrantVectorStore(
                        qdrantClient,
                        selectedOptions);
                });
        }

        return builder;
    }
}
